#include <stdio.h>
#include <stdlib.h>

typedef struct PStack { int val; struct PStack *next; } PStack;

PStack* pstack_push(PStack *old, int val) {
    PStack *n = malloc(sizeof(PStack));
    n->val = val; n->next = old; return n;
}

int pstack_peek(PStack *s) { return s->val; }
PStack* pstack_pop(PStack *s) { return s->next; }

void pstack_print(PStack *s) {
    while (s) { printf("%d ", s->val); s = s->next; }
    printf("\n");
}

int main() {
    PStack *s0 = NULL;
    PStack *s1 = pstack_push(s0, 10);
    PStack *s2 = pstack_push(s1, 20);
    PStack *s3 = pstack_push(s2, 30);
    printf("s3: "); pstack_print(s3);
    printf("s2: "); pstack_print(s2);
    printf("s1: "); pstack_print(s1);
    return 0;
}
